For any given number n, print Hollow and solid Squares and Rhombus made with stars(*). Examples:  

Input : n = 4
Output : 
Solid Rhombus:
   ****
  ****
 ****
****

Hollow Rhombus:
   ****
  *  *
 *  *
****

1. Solid Rhombus : Making Solid Rhombus is a bit similar to making solid square rather than the concept that for each ith row we have n-i blank spaces before stars as: - - - **** - - **** - **** **** 2. Hollow Rhombus : Formation of Hollow Rhombus uses the idea behind formation of hollow square and solid rhombus. A hollow square with n-i blank spaces before stars in each ith rows result in formation of hollow rhombus.  



            C++

    // C++ program to print 
// hollow and solid rhombus patterns 

#include <bits/stdc++.h> 
using namespace std; 


// Function for Solid Rhombus 
void solidRhombus(int rows) 
{ 
    int i, j; 
    for (i=1; i<=rows; i++) 
    { 
        // Print trailing spaces 
        for (j=1; j<=rows - i; j++) 
            cout << " "; 

        // Print stars after spaces 
        for (j=1; j<=rows; j++) 
            cout << "*"; 

        // Move to the next line/row 
        cout << "\n"; 
    } 
} 

// Function for Rhombus 
void hollowRhombus(int rows) 
{ 
    int i, j; 
    for (i=1; i<=rows; i++) 
    { 
        // Print trailing spaces 
        for (j=1; j<=rows - i; j++) 
            cout << " "; 

        // Print stars after spaces 
        // Print stars for each solid rows 
        if (i==1 || i==rows) 
            for (j=1; j<=rows; j++) 
                cout << "*"; 

        // stars for hollow rows 
        else
            for (j=1; j<=rows; j++) 
                if (j==1 || j==rows) 
                    cout << "*"; 
                else
                    cout << " "; 
        // Move to the next line/row 
        cout << "\n"; 
    } 
} 

// utility program to print all patterns 
void printPattern(int rows) 
{ 
    cout << "\nSolid Rhombus:\n"; 
    solidRhombus(rows); 

    cout << "\nHollow Rhombus:\n"; 
    hollowRhombus(rows); 
} 

// driver program 
int main() 
{ 
    int rows = 5; 
    printPattern (rows); 
    return 0; 
} 


