Time Complexity: O(r2), where r represents the given number of rows.Auxiliary Space: O(1), no extra space is required, so it is a constant.

Approach:

solidRhombus function:

Initialize variables i and j.Loop from i = 1 to n:Loop from j = 1 to n - i and print spaces.Loop from j = 1 to n and print asterisks.Print a new line.End of function. 

hollowRhombus function:

Initialize variables i and j.Loop from i = 1 to n:Loop from j = 1 to n - i and print spaces.Loop from j = 1 to n:If i = 1 or i = n or j = 1 or j = n, print an asterisk.Else, print a space.Print a new line.End of function.

            C

    #include <stdio.h>

// function to print solid rhombus
void solidRhombus(int n) {
    int i, j;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n - i; j++) {
            printf(" ");
        }
        for (j = 1; j <= n; j++) {
            printf("*");
        }
        printf("\n");
    }
}

// function to print hollow rhombus
void hollowRhombus(int n) {
    int i, j;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n - i; j++) {
            printf(" ");
        }
        for (j = 1; j <= n; j++) {
            if (i == 1 || i == n || j == 1 || j == n) {
                printf("*");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

int main() {
    int n = 5;
    printf("Solid Rhombus:\n");
    solidRhombus(n);

    printf("Hollow Rhombus:\n");
    hollowRhombus(n);

    return 0;
}


